{
  "PROP-6a4369e9-inv-008": {
    "property_id": "PROP-6a4369e9-inv-008",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-008",
      "classification": "potential-vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_availability_checker.rs::put_rpc_custody_columns::L247-263",
      "proof_trace": "Gossip path validates index range before KZG verification (L480\u2192L535). RPC path performs KZG verification without index validation (L247-249), then silently filters invalid indices (L261). This allows attackers to force expensive KZG operations on invalid data without penalty.",
      "attack_scenario": "Malicious peer sends DataColumnsByRoot responses with index >= 128. Node performs costly KZG verification before filtering. Attacker repeats to exhaust CPU resources. No peer penalty applied since validation succeeds but columns are silently dropped.",
      "checklist_id": "PROP-6a4369e9-inv-008"
    },
    "text": "sidecar.index must be in range [0, NUMBER_OF_COLUMNS) to be accepted.",
    "assertion": "forall sidecar: accepted(sidecar) => sidecar.index >= 0 && sidecar.index < NUMBER_OF_COLUMNS",
    "covers": "SG-002",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

